import json
from pathlib import Path
p=Path('/mnt/data/LSF/data/officeqa/json/treasury_bulletin_2016_03.json')
obj=json.loads(p.read_text())
# recursively search for strings containing target words
hits=[]
def walk(x, path='root'):
    if isinstance(x, dict):
        for k,v in x.items():
            walk(v, f'{path}.{k}')
    elif isinstance(x, list):
        for i,v in enumerate(x):
            walk(v, f'{path}[{i}]')
    elif isinstance(x, str):
        s=x.lower()
        if any(t in s for t in ['michigan','reuters','sentiment','confidence']):
            hits.append((path, x))
walk(obj)
print('HITS', len(hits))
for path, x in hits[:50]:
    print(path)
    print(x[:500].replace('\\n',' '))
    print('---')
PY"

